package dev.pedro.learning.ecommerce.notification.provider;import jakarta.enterprise.context.ApplicationScoped;import java.util.concurrent.atomic.AtomicInteger;@ApplicationScoped public class FakeEmailProvider{private volatile EmailProviderMode mode=EmailProviderMode.NORMAL;private volatile int failFirstN=3;private volatile long delayMs=3000;private final AtomicInteger calls=new AtomicInteger();private final AtomicInteger successes=new AtomicInteger();private final AtomicInteger failures=new AtomicInteger();public void send(String email,String subject){int call=calls.incrementAndGet();if(mode==EmailProviderMode.SLOW)sleep(delayMs);if(mode==EmailProviderMode.ALWAYS_FAIL)fail("Email provider unavailable");if(mode==EmailProviderMode.FAIL_FIRST_N_ATTEMPTS&&call<=failFirstN)fail("Configured email failure "+call+"/"+failFirstN);successes.incrementAndGet();}private void fail(String message){failures.incrementAndGet();throw new IllegalStateException(message);}private void sleep(long millis){try{Thread.sleep(millis);}catch(InterruptedException e){Thread.currentThread().interrupt();throw new IllegalStateException("Email provider interrupted",e);}}public void mode(EmailProviderMode mode){this.mode=mode;}public EmailProviderMode mode(){return mode;}public void failFirstN(int n){failFirstN=Math.max(0,n);}public int failFirstN(){return failFirstN;}public void delayMs(long ms){delayMs=Math.max(0,ms);}public long delayMs(){return delayMs;}public int calls(){return calls.get();}public int successes(){return successes.get();}public int failures(){return failures.get();}public void reset(){mode=EmailProviderMode.NORMAL;failFirstN=3;delayMs=3000;calls.set(0);successes.set(0);failures.set(0);}}